import type { Kysely } from "kysely";

import type { Database, JsonObject } from "../db/schema.ts";

export interface Utm {
  source?: string;
  medium?: string;
  campaign?: string;
  term?: string;
  content?: string;
}

/** An event that has already passed validation (step 2 adds the endpoint that validates). */
export interface NewEvent {
  /** Generated by the sender; makes retries safe. */
  eventId: string;
  name: string;
  /** Sender's clock. */
  occurredAt: Date;
  path: string;
  referrer?: string;
  utm?: Utm;
  properties?: JsonObject;
}

export interface StoreResult {
  /** Events stored for the first time. */
  inserted: number;
  /** Events skipped because this project already has an event with the same ID. */
  duplicates: number;
}

/**
 * Stores events for one project in a single statement, so either all new
 * events are saved or none are.
 *
 * An event whose ID is already stored is skipped, not stored again. Senders
 * retry when they do not hear back, so the same event can arrive twice; this
 * keeps every event counted once.
 */
export async function storeEvents(
  db: Kysely<Database>,
  projectId: string,
  events: readonly NewEvent[],
): Promise<StoreResult> {
  if (events.length === 0) {
    return { inserted: 0, duplicates: 0 };
  }

  const result = await db
    .insertInto("events")
    .values(
      events.map((event) => ({
        project_id: projectId,
        event_id: event.eventId,
        name: event.name,
        occurred_at: event.occurredAt,
        path: event.path,
        referrer: event.referrer,
        utm_source: event.utm?.source,
        utm_medium: event.utm?.medium,
        utm_campaign: event.utm?.campaign,
        utm_term: event.utm?.term,
        utm_content: event.utm?.content,
        properties: event.properties,
      })),
    )
    .onConflict((conflict) => conflict.columns(["project_id", "event_id"]).doNothing())
    .executeTakeFirst();

  const inserted = Number(result.numInsertedOrUpdatedRows ?? 0n);
  return { inserted, duplicates: events.length - inserted };
}
